CREATE OR REPLACE TRIGGER immutable_prompt BEFORE UPDATE OR DELETE ON onet_matching.prompt_contract FOR EACH ROW EXECUTE FUNCTION onet_matching.immutable();
CREATE OR REPLACE TRIGGER immutable_truncate BEFORE TRUNCATE ON onet_matching.prompt_contract FOR EACH STATEMENT EXECUTE FUNCTION onet_matching.immutable();
CREATE OR REPLACE TRIGGER retention_freeze BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON onet_matching.prompt_contract FOR EACH STATEMENT EXECUTE FUNCTION retention.freeze_writes();
COMMIT;
